/* ============================================
   WellStream Platform — Design System & Styles
   ============================================ */

/* --- CSS Custom Properties (OKLCH with hex fallbacks) --- */
:root {
  /* Backgrounds */
  --bg-primary: #0D1B2A;
  --bg-secondary: #1B2838;
  --bg-card: #162233;
  --bg-card-hover: #1c2d42;
  --bg-surface: #1e3348;

  /* Brand */
  --brand-navy: #15295A;
  --brand-green: #6CC24A;

  /* Accents */
  --accent-blue: #00B4D8;
  --accent-blue-dark: #0077B6;
  --accent-teal: #00B4D8;
  --accent-green: #6CC24A;

  /* Text */
  --text-primary: #FFFFFF;
  --text-secondary: #B0BEC5;
  --text-muted: #78909C;
  --text-accent: #00B4D8;

  /* Borders */
  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-accent: rgba(0, 180, 216, 0.3);

  /* Shadows */
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.3);
  --shadow-elevated: 0 8px 40px rgba(0, 0, 0, 0.4);

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;

  /* OKLCH values for modern browsers */
  --oklch-accent-blue: oklch(72% 0.12 210);
  --oklch-accent-dark: oklch(45% 0.12 240);
  --oklch-green: oklch(73% 0.20 135);
  --oklch-bg-primary: oklch(18% 0.05 250);
  --oklch-bg-secondary: oklch(25% 0.04 250);
}

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  font-size: 16px;
  overflow-x: hidden;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--text-primary);
}

img {
  max-width: 100%;
  display: block;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.text-label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent-blue);
}

.text-secondary {
  color: var(--text-secondary);
}

.text-muted {
  color: var(--text-muted);
}

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-xl);
}

.section {
  padding: var(--space-4xl) 0;
}

.section--alt {
  background-color: var(--bg-secondary);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-subtle);
  height: var(--nav-height);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-xl);
}

.nav__logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.nav__logo-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  font-weight: 900;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav__link {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 500;
  position: relative;
  transition: color var(--transition-fast);
}

.nav__link:hover {
  color: var(--text-primary);
}

/* Dropdown */
.nav__dropdown {
  position: relative;
}

.nav__dropdown-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  background: none;
  border: none;
  font-family: inherit;
  transition: color var(--transition-fast);
}

.nav__dropdown-toggle:hover {
  color: var(--text-primary);
}

.nav__dropdown-arrow {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav__dropdown.open .nav__dropdown-arrow {
  transform: rotate(180deg);
}

.nav__dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  min-width: 200px;
  padding: var(--space-sm);
  box-shadow: var(--shadow-elevated);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-fast), visibility var(--transition-fast);
}

.nav__dropdown.open .nav__dropdown-menu {
  opacity: 1;
  visibility: visible;
}

.nav__dropdown-item {
  display: block;
  padding: var(--space-sm) var(--space-md);
  color: var(--text-secondary);
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.nav__dropdown-item:hover {
  color: var(--text-primary);
  background: rgba(0, 180, 216, 0.1);
}

.nav__cta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: 0.625rem 1.25rem;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.nav__cta:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(0, 180, 216, 0.3);
  color: var(--text-primary);
}

/* Mobile menu toggle */
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: var(--space-sm);
}

.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: var(--transition-fast);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.5rem;
  font-family: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.btn--primary {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-blue-dark));
  color: var(--text-primary);
}

.btn--primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 180, 216, 0.35);
  color: var(--text-primary);
}

.btn--secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-accent);
}

.btn--secondary:hover {
  background: rgba(0, 180, 216, 0.1);
  border-color: var(--accent-blue);
  color: var(--text-primary);
}

.btn--green {
  background: var(--brand-green);
  color: var(--bg-primary);
}

.btn--green:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(108, 194, 74, 0.35);
}

.btn--lg {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

/* --- Hero --- */
.hero {
  min-height: 80vh;
  display: flex;
  align-items: center;
  padding-top: var(--nav-height);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(0, 180, 216, 0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0, 119, 182, 0.06) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content {
  position: relative;
  z-index: 1;
  max-width: 720px;
}

.hero__label {
  margin-bottom: var(--space-md);
}

.hero__title {
  margin-bottom: var(--space-lg);
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero__subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-secondary);
  margin-bottom: var(--space-2xl);
  line-height: 1.7;
}

.hero__actions {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.hero--compact {
  min-height: auto;
  padding-top: calc(var(--nav-height) + var(--space-4xl));
  padding-bottom: var(--space-3xl);
}

/* --- Tabs --- */
.tabs {
  width: 100%;
}

.tabs__list {
  display: flex;
  gap: var(--space-xs);
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: var(--space-2xl);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.tabs__list::-webkit-scrollbar {
  display: none;
}

.tabs__tab {
  padding: var(--space-md) var(--space-lg);
  font-family: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-muted);
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.tabs__tab:hover {
  color: var(--text-secondary);
}

.tabs__tab--active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

.tabs__panel {
  display: none;
}

.tabs__panel--active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.card:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-accent);
  transform: translateY(-4px);
  box-shadow: var(--shadow-card);
}

.card__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-md);
  font-size: 1.25rem;
}

.card__icon--blue {
  background: rgba(0, 180, 216, 0.12);
  color: var(--accent-blue);
}

.card__icon--green {
  background: rgba(108, 194, 74, 0.12);
  color: var(--accent-green);
}

.card__icon--navy {
  background: rgba(21, 41, 90, 0.5);
  color: var(--accent-blue);
}

.card__title {
  font-size: 1.125rem;
  margin-bottom: var(--space-sm);
}

.card__desc {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Grid Layouts --- */
.grid {
  display: grid;
  gap: var(--space-xl);
}

.grid--2 {
  grid-template-columns: repeat(2, 1fr);
}

.grid--3 {
  grid-template-columns: repeat(3, 1fr);
}

.grid--6 {
  grid-template-columns: repeat(3, 1fr);
}

/* --- Feature Banner --- */
.featured-banner {
  background: linear-gradient(135deg, var(--brand-navy) 0%, #1a3a6e 100%);
  border: 1px solid rgba(0, 180, 216, 0.2);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl) var(--space-3xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
  position: relative;
  overflow: hidden;
}

.featured-banner::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 300px;
  height: 100%;
  background: linear-gradient(135deg, transparent, rgba(0, 180, 216, 0.08));
  pointer-events: none;
}

.featured-banner__label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent-blue);
  margin-bottom: var(--space-xs);
}

.featured-banner__product {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.featured-banner__tagline {
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

/* --- Stats (Circular) --- */
.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2xl);
  text-align: center;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-md);
}

.stat__circle {
  position: relative;
  width: 140px;
  height: 140px;
}

.stat__circle svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.stat__circle-bg {
  fill: none;
  stroke: var(--border-subtle);
  stroke-width: 6;
}

.stat__circle-fill {
  fill: none;
  stroke: var(--accent-blue);
  stroke-width: 6;
  stroke-linecap: round;
  stroke-dasharray: 408;
  stroke-dashoffset: 408;
  transition: stroke-dashoffset 1.5s ease;
}

.stat__value {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2rem;
  font-weight: 800;
}

.stat__label {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  max-width: 200px;
}

/* --- Accordion --- */
.accordion {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.accordion__item {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-base);
}

.accordion__item--open {
  border-color: var(--border-accent);
}

.accordion__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-lg) var(--space-xl);
  cursor: pointer;
  font-weight: 600;
  font-size: 1.125rem;
  background: none;
  border: none;
  color: var(--text-primary);
  width: 100%;
  text-align: left;
  font-family: inherit;
  transition: background var(--transition-fast);
}

.accordion__header:hover {
  background: rgba(0, 180, 216, 0.04);
}

.accordion__icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(0, 180, 216, 0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.accordion__item--open .accordion__icon {
  transform: rotate(45deg);
  background: var(--accent-blue);
}

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.accordion__item--open .accordion__body {
  max-height: 300px;
}

.accordion__content {
  padding: 0 var(--space-xl) var(--space-lg);
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* --- Timeline --- */
.timeline {
  display: flex;
  flex-direction: column;
  gap: var(--space-2xl);
}

.timeline__item {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.timeline__duration {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--accent-blue);
}

.timeline__label {
  font-size: 0.9375rem;
  color: var(--text-secondary);
  margin-bottom: var(--space-sm);
}

.timeline__bar-track {
  width: 100%;
  height: 8px;
  background: var(--border-subtle);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.timeline__bar-fill {
  height: 100%;
  border-radius: var(--radius-full);
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-blue-dark));
  width: 0%;
  transition: width 1.5s ease;
}

/* --- Testimonials Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel__slide {
  min-width: 100%;
  padding: var(--space-2xl);
}

.carousel__quote {
  font-size: 1.125rem;
  font-style: italic;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--space-lg);
  position: relative;
  padding-left: var(--space-xl);
}

.carousel__quote::before {
  content: '\201C';
  position: absolute;
  left: 0;
  top: -10px;
  font-size: 3rem;
  color: var(--accent-blue);
  font-style: normal;
  line-height: 1;
}

.carousel__author {
  font-weight: 600;
  color: var(--text-primary);
}

.carousel__role {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-lg);
}

.carousel__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-subtle);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel__dot--active {
  background: var(--accent-blue);
  transform: scale(1.2);
}

/* --- Diagram (SVG/CSS) --- */
.diagram {
  display: flex;
  justify-content: center;
  align-items: stretch;
  gap: var(--space-2xl);
  padding: var(--space-2xl);
}

.diagram__pillar {
  flex: 1;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;
  position: relative;
  transition: all var(--transition-base);
}

.diagram__pillar:hover {
  border-color: var(--border-accent);
  transform: translateY(-4px);
}

.diagram__pillar-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto var(--space-md);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.diagram__pillar-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.diagram__pillar-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.diagram__connector {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-blue);
  font-size: 1.5rem;
  flex-shrink: 0;
}

/* --- Benefits --- */
.benefits {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: var(--space-xl);
}

.benefit {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.benefit__icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: rgba(0, 180, 216, 0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-blue);
  font-size: 1.125rem;
}

.benefit__title {
  font-size: 1.0625rem;
  font-weight: 700;
}

.benefit__desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* --- Security Features --- */
.security-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.security-feature {
  display: flex;
  gap: var(--space-lg);
  padding: var(--space-lg);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}

